/* 05-motion.css */
/* Only the newest real message receives a short print-registration sweep. */
#chat > .last_mes:not(.smallSysMes) > .mes_block::after {
    content: "";
    position: absolute;
    z-index: 2;
    top: 0;
    left: 20px;
    width: min(210px, 46%);
    height: 3px;
    pointer-events: none;
    background-color: var(--ef-signal);
    background-image: var(--ef-contours);
    transform-origin: left;
}

@media (prefers-reduced-motion: no-preference) {
    #chat > .last_mes:not(.smallSysMes) > .mes_block::after {
        animation: ef-registration-sweep 260ms cubic-bezier(0.2, 0.75, 0.2, 1) both;
    }

    #top-settings-holder > .drawer > .drawer-content.openDrawer {
        animation: ef-menu-resolve var(--ef-shift) cubic-bezier(0.2, 0.72, 0.2, 1) both;
    }
}

@keyframes ef-registration-sweep {
    from {
        opacity: 0;
        transform: scaleX(0.08);
    }

    to {
        opacity: 1;
        transform: scaleX(1);
    }
}

/* Official menu-category changes resolve from a short blank/dim interval. */
@keyframes ef-menu-resolve {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

body.reduced-motion #top-settings-holder > .drawer > .drawer-content {
    animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
    #chat > .mes,
    #send_form,
    #send_form::before,
    #send_but,
    #top-settings-holder > .drawer > .drawer-toggle,
    #top-settings-holder > .drawer > .drawer-toggle::after {
        scroll-behavior: auto !important;
        animation: none !important;
        transition: none !important;
    }

    #chat > .last_mes:not(.smallSysMes) > .mes_block::after,
    #send_form::before {
        transform: scaleX(1) !important;
    }
}

