/* 09-floor-index.css */
/*
 * 楼层编号：官方长图的两位数分节标记，落在头像左侧的页边槽。
 * 编号取 ST 原生 mesid，和 /go 等命令看到的楼层号一致；个位数补零成两位，
 * 保持长图的编号节奏。单位数值域只有 0–9，所以一条 :is() 即可穷举。
 * padding-top 让编号落到角色名一行的基线附近，而非贴头像顶 —— 官方编号是与
 * 标题成组的，不是浮在角落。
 */

#chat > .mes:not(.smallSysMes)::before {
    content: attr(mesid);
    flex: 0 0 30px;
    padding-top: 15px;
    color: var(--ef-muted);
    font: 400 13px/1 var(--ef-font-number);
    font-variant-numeric: tabular-nums;
    letter-spacing: 0.04em;
    text-align: right;
    -webkit-user-select: none;
    user-select: none;
}

#chat > .mes:not(.smallSysMes):is(
    [mesid="0"], [mesid="1"], [mesid="2"], [mesid="3"], [mesid="4"],
    [mesid="5"], [mesid="6"], [mesid="7"], [mesid="8"], [mesid="9"]
)::before {
    content: "0" attr(mesid);
}

@media (max-width: 700px) {
    #chat > .mes:not(.smallSysMes)::before {
        flex-basis: 20px;
        font-size: 11px;
    }
}

/* 10-section-band.css */
/*
 * 分节横条：官号长图的章节头，两行结构。
 *
 * 官方构造（实测 2025-12-09-dijiang-update-02.png，画布 1000px）：
 *   上层：炭灰块内嵌黄色两位编号 + 灰条白字英文标签，宽度贴合内容不铺满，条高 35px
 *   下层：标题在**白纸底**上（不是压在黄条上），黄条从标题右侧起填满剩余宽度，行高 66px
 *   标题字高 46px，正文字高 26px —— 标题/正文 = 1.77×，层级靠字号撑不靠字重
 *
 * 只挂真实存在的分节标题；聊天区没有原生分节边界（日期条是卡片正则产物），
 * 逐条消息的编号由 09-floor-index 承担，两个装置不叠加。
 * 编号用 counter 而非写死：分节数量由宿主决定，写死会在 ST 增减区块时说谎。
 *
 * 已知简化：官方上层条是「炭灰块+灰条」两段两色、编号为黄字，两个伪元素凑不出
 * 三个盒子，所以用双色渐变底还原分段、文字统一取纸白。黄条不补写来源不明的微缩英文。
 */

#chat > .welcomePanel {
    counter-reset: ef-section 0;
}

#chat > .welcomePanel .recentChatsTitle {
    display: grid !important;
    grid-template-columns: max-content 1fr;
    align-items: stretch;
    width: 100% !important;
    counter-increment: ef-section;
    padding: 0 !important;
    color: var(--ef-ink) !important;
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    font-family: var(--ef-font-display) !important;
    font-size: 26px !important;
    font-weight: 900 !important;
    letter-spacing: 0.01em;
    line-height: 1.2 !important;
    text-shadow: none !important;
}

/* 上层条：横跨整行占位，再用 justify-self 收成内容宽度，背景才不会铺满。 */
#chat > .welcomePanel .recentChatsTitle::before {
    content: counter(ef-section, decimal-leading-zero) "  ARKNIGHTS: ENDFIELD";
    grid-row: 1;
    grid-column: 1 / -1;
    justify-self: start;
    padding: 3px 9px 3px 8px;
    color: var(--ef-paper-hi);
    background: linear-gradient(to right, var(--ef-block) 0 2.6em, var(--ef-label) 2.6em);
    font: 600 11px/1.35 var(--ef-font-body);
    letter-spacing: 0.14em;
    white-space: pre;
}

/* 黄条：与标题同行，从标题右侧起填满剩余宽度。 */
#chat > .welcomePanel .recentChatsTitle::after {
    content: "";
    grid-row: 2;
    grid-column: 2;
    display: block;
    background: var(--ef-signal);
}

/* 标题自动落到第二行第一格；容器的字号字重由它继承。 */
#chat > .welcomePanel .recentChatsTitle {
    padding-right: 0 !important;
}

@media (max-width: 700px) {
    #chat > .welcomePanel .recentChatsTitle {
        font-size: 21px !important;
    }

    #chat > .welcomePanel .recentChatsTitle::before {
        font-size: 10px;
        letter-spacing: 0.1em;
    }
}

/* 11-archive-marks.css */
/*
 * 档案页记号：页眉套准色条与 // 标签前缀。
 *
 * 套准色条实测（2025-12-09-dijiang-update-02.png，画布 1000px，行 y=17–21）：
 *   高 5px；洋红 #d025ce 占 x 61–186，淡黄 #fcf56d 占 190–292，青绿 #34e3ad 占 295–605。
 *   三段不等宽，起于 6.1%、止于 60.5%，右侧留空 —— 是印刷套准标记，不是装饰满铺。
 *   注意这里的淡黄是套准色，不是主强调的 --ef-signal 纯黄，两者不可混用。
 *
 * // 前缀是官方图注的固定记号（形如「// 行迹高塔」），只给真实的子块标签，
 * 不铺到普通正文或按钮上。
 */

#chat > .welcomePanel {
    position: relative;
}

#chat > .welcomePanel::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 5px;
    background: linear-gradient(
        to right,
        transparent 0 6.1%,
        var(--ef-calib-m) 6.1% 18.7%,
        transparent 18.7% 19%,
        var(--ef-calib-y) 19% 29.3%,
        transparent 29.3% 29.5%,
        var(--ef-calib-c) 29.5% 60.5%,
        transparent 60.5%
    );
    pointer-events: none;
}

#chat > .welcomePanel .welcomeHeader {
    padding-top: 13px !important;
}

/*
 * 图注：官方形态是「深灰细竖条 + 黄块 + 白底斜体 // 标签 + 右侧黄条」。
 * 实测（update-02，画布 1000px，y≈1155）：深竖条约 6px，黄块约 25px，// 为斜体。
 * 挂在推理块头部 —— 它是聊天里唯一语义对得上的「子块标签」。
 */

#chat > .mes .mes_reasoning_summary .mes_reasoning_header {
    align-items: stretch !important;
    padding: 0 !important;
    border-radius: 0 !important;
    background: linear-gradient(
        to right,
        var(--ef-block) 0 6px,
        var(--ef-signal) 6px 31px,
        var(--ef-paper-hi) 31px
    ) !important;
}

#chat > .mes .mes_reasoning_summary .mes_reasoning_header::before {
    content: "//";
    margin-left: 39px;
    padding-right: 6px;
    color: var(--ef-ink);
    font-style: italic;
    font-weight: 800;
    letter-spacing: 0.02em;
}

#chat > .mes .mes_reasoning_summary .mes_reasoning_header_title {
    padding: 3px 0 !important;
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-display) !important;
    font-weight: 700 !important;
}

/*
 * 不给正文的「」和“”加任何装饰。
 * 官方长图里角括号是「标题中引用专有名词」的排版记号，但在聊天正文里它就是对话引号 ——
 * 实测 40 个聊天记录中出现 40,765 次「」与 71,176 次“”，几乎全是台词。
 * 上色或加重会把满屏对白染成装饰，与「装饰降低对比度、正文保持高可读」直接冲突。
 */

/* 12-section-closure.css */
/*
 * 章节收束灰带：官方长图用约 #e5e5e5 的中灰留白分开大章节，
 * 160px 结构网格贯穿，交点带断开的套准斜线，等高线只在左侧局部出现。
 *
 * 普通聊天消息没有原生章节语义；纯 JSON/CSS 不能可靠推断剧情分段。
 * 因此这里只挂在首页“最近聊天”这个真实区块的末尾，作为档案索引与正文的过渡。
 */

#chat > .welcomePanel::after {
    content: "";
    box-sizing: border-box;
    display: block;
    flex: 0 0 84px;
    align-self: stretch;
    width: 100%;
    min-height: 84px;
    background-color: var(--ef-workbench);
    background-image: var(--ef-contours-light), var(--ef-gray-grid);
    background-size: min(320px, 58%) 96px, 160px 160px;
    background-position: -10px center, 0 0;
    background-repeat: no-repeat, repeat;
    border-top: 1px solid var(--ef-line);
    border-bottom: 1px solid var(--ef-line);
    pointer-events: none;
}

@media (max-width: 700px) {
    #chat > .welcomePanel::after {
        flex-basis: 48px;
        min-height: 48px;
        background-size: min(250px, 72%) 64px, 160px 160px;
    }
}

/* 13-topbar-groups.css */
/* Top bar grouping: three functional clusters, separated like a printed control strip. */

/* The holder already has three equal groups; mark only their two real boundaries. */
#top-settings-holder > #WI-SP-button > .drawer-toggle::before,
#top-settings-holder > #extensions-settings-button > .drawer-toggle::before {
    content: "";
    position: absolute;
    top: 8px;
    bottom: 8px;
    left: 0;
    width: 1px;
    background: rgba(238, 240, 237, 0.24);
    pointer-events: none;
}

/* The in-game settings strip uses a complete yellow tile for the active tab. */
#top-settings-holder > .drawer > .drawer-toggle:has(> .drawer-icon.openIcon) {
    color: var(--ef-ink) !important;
